  "-EX",
  " GX",
  "-GX",
  " V",
  " VMAX",
  " VSTAR",
  " V-UNION",
  " LV.X",
  " BREAK",
  " Prime",
  " LEGEND",
  " Star",
  " \u03B4",
  " \u25C7",
  " \u2606"
